import logging
import re
from collections import defaultdict
from datetime import datetime, timedelta

from itertools import filterfalse
import pytz
from dateutil.parser import parse
from lxml import etree

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class PMSetupEntryFilter(object):
    def __init__(self,
                 local_executor,
                 for_last=None,
                 intervals=None,
                 **kwargs):
        super(PMSetupEntryFilter, self).__init__(**kwargs)
        self._for_last = for_last
        self._intervals = [str(item) for item in intervals] if intervals else None
        self._local_executor = local_executor
        self._allowed_since = None
        self._filter_criteria = []

    @staticmethod
    def _current_datetime():
        return datetime.now(pytz.utc)

    def initialise_filter_criteria(self):
        self._allowed_since = self._current_datetime() - self._for_last if self._for_last else None
        if self._allowed_since:
            self._filter_criteria.append(
                lambda x: (
                    parse(re.match(r'(\d+-\d+-\d+T\d+:\d+:\d+(?:\.\d+)?[+-]\d+:\d+)',
                                   x.get("startTime")).group(0))
                    + timedelta(minutes=int(x.get("interval")))
                    >= self._allowed_since))
        if self._intervals:
            self._filter_criteria.append(lambda x: x.get("interval") in self._intervals)

    def remove_unwanted_files(self, target_dir):
        if self._allowed_since:
            command = (r"""shopt -s nullglob;"""
                       r""" grep -oP 'startTime="\K.*?(?=")" interval=".*?(?=")' *.{xml,raw} /dev/null || true""")
            lines = self._local_executor.execute(("cd '{}';".format(target_dir) + command).encode('utf-8')).splitlines()
            file_name_to_start_times = defaultdict(list)
            for line in lines:
                file_name, start_time = line.split(b":", 1)
                file_name_to_start_times[file_name].append(start_time.decode('utf-8').split('" interval="'))
            for file_name, start_times in file_name_to_start_times.items():
                if all(parse(
                        re.match(r'(\d+-\d+-\d+T\d+:\d+:\d+(?:\.\d+)?[+-]\d+:\d+)',
                                 start_time[0]).group(0)) + timedelta(minutes=int(start_time[1])) < self._allowed_since
                       for start_time in start_times):
                    logger.debug(
                        "Removing %s as it not satisfies filter criteria as start_times:%s is less than %s",
                        file_name, start_times, self._allowed_since)
                    self._local_executor.execute(
                        "cd '{target_dir}'; rm -f '{file_name}'".format(
                            target_dir=target_dir,
                            file_name=file_name.decode('utf-8')).encode('utf-8'))
                else:
                    logger.debug(
                        "%s satisfies filter criteria as all start_times:%s is not less than %s",
                        file_name, start_times, self._allowed_since)

    def remove_unwanted_pmsetup_tags(self, pm_file):
        """
        Remove unwanted pm data (based on given since and/or intervals) from PM file and if there is no relevant data
        left afterward, then remove the file itself.

        :param str pm_file: pm_file path
        """
        logger.debug("Checking %s for entry since %r and intervals %r",
                     pm_file, self._allowed_since, self._intervals)
        tree = self._read_xml(pm_file)
        all_pmsetup = tree.iterfind(".//PMSetup")
        unwanted_pmsetup = self._get_unwanted_value_generator(
            all_pmsetup, inclusive_filter_criteria=self._filter_criteria)
        for unwanted in unwanted_pmsetup:
            unwanted.getparent().remove(unwanted)
        self._write_xml(tree, pm_file)
        if tree.find(".//PMSetup") is None:
            logger.debug("Removing %s as it not satisfies filter criteria", pm_file)
            self._local_executor.execute("rm -f '{pm_file}'".format(
                pm_file=pm_file).encode('utf-8'))
        else:
            logger.debug("Rewriting %s with filtered PM values", pm_file)
            self._write_xml(tree, pm_file)

    @staticmethod
    def _read_xml(pm_file):
        return etree.parse(pm_file)

    @staticmethod
    def _get_unwanted_value_generator(all_pmsetup, inclusive_filter_criteria=None):
        if inclusive_filter_criteria:
            all_pmsetup = filterfalse(
                lambda a: all(criteria(a) for criteria in inclusive_filter_criteria),
                all_pmsetup)
        return all_pmsetup

    @staticmethod
    def _write_xml(etree_obj, pm_file):
        etree_obj.write(pm_file, encoding=etree_obj.docinfo.encoding, xml_declaration=True,
                        standalone=etree_obj.docinfo.standalone)
